const effPrice = (p) => (p.sale_price != null && p.sale_price < p.price ? p.sale_price : p.price);
const discount = (p) => (p.sale_price != null && p.sale_price < p.price ? Math.round((1 - p.sale_price / p.price) * 100) : 0);

const csrf = (ctx) => h`<input type="hidden" name="_csrf" value="${ctx.session ? ctx.session.csrf : ''}">`;

function layout(ctx, { title, desc, body, nav = {} }) {
  const flash = ctx.takeFlash();
  const user = ctx.user;
  const cats = nav.brands || [];
  return h`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title ? title + ' | ' : ''}${cfg.SHOP_NAME}</title>
<meta name="description" content="${desc || 'Genuine mobile phones, tablets and accessories in Sri Lanka. Islandwide delivery, cash on delivery, warranty on every product.'}">
<meta name="referrer" content="same-origin">
<link rel="icon" href="data:,">
<link rel="stylesheet" href="/static/store.css">
</head>
<body>
<div class="topbar"><div class="wrap">
  <span>Genuine products &middot; Islandwide delivery &middot; Cash on delivery</span>
  <span><a href="tel:${cfg.SHOP_PHONE.replace(/\s/g, '')}">${cfg.SHOP_PHONE}</a> &middot; <a href="https://wa.me/${cfg.WHATSAPP}" rel="noopener noreferrer">WhatsApp</a></span>
</div></div>
<header class="site-header"><div class="wrap head-row">
  <input type="checkbox" id="menu-toggle" class="menu-toggle" aria-label="Toggle menu">
  <label for="menu-toggle" class="burger" aria-hidden="true"><span></span><span></span><span></span></label>
  <a class="logo" href="/"><span class="logo-mark">&#9742;</span>${cfg.SHOP_NAME}</a>
  <form class="search" action="/shop" method="get" role="search">
    <input type="search" name="q" maxlength="60" placeholder="Search phones, brands, accessories..." value="${ctx.query && ctx.query.q ? ctx.query.q : ''}" aria-label="Search">
    <button type="submit">Search</button>
  </form>
  <nav class="acct" aria-label="Account">
    ${user ? h`<a href="/account">${user.name.split(' ')[0]}</a>` : h`<a href="/login">Login / Register</a>`}
    <a class="cart-link" href="/cart">Cart <b>${nav.cartCount || 0}</b></a>
  </nav>
  <nav class="main-nav" aria-label="Main">
    <a href="/">Home</a>
    <div class="dd"><a href="/shop?category=phone">Mobile Phones</a>
      <div class="dd-menu">${cats.map((b) => h`<a href="/shop?brand=${b.slug}">${b.name}</a>`)}</div></div>
    <a href="/shop?category=tablet">Tablets</a>
    <a href="/shop?category=accessory">Accessories</a>
    <a href="/shop">Shop All</a>
    <a class="offer" href="/shop?sale=1">Special Offers</a>
    <a href="/contact">Contact</a>
  </nav>
</div></header>
<main class="wrap" id="main">
${flash ? h`<div class="flash ${flash.type}" role="status">${flash.msg}</div>` : ''}
${body}
</main>
<footer class="site-footer"><div class="wrap foot-grid">
  <div><h4>${cfg.SHOP_NAME}</h4><p>Your trusted mobile store. Genuine products, easy ordering, islandwide delivery.</p></div>
  <div><h4>Shop</h4><a href="/shop?category=phone">Mobile Phones</a><a href="/shop?category=tablet">Tablets</a><a href="/shop?category=accessory">Accessories</a><a href="/shop?sale=1">Special Offers</a></div>
  <div><h4>Help</h4><a href="/policy/returns">Returns &amp; Warranty</a><a href="/policy/privacy">Privacy Policy</a><a href="/policy/terms">Terms &amp; Conditions</a><a href="/contact">Contact us</a></div>
  <div><h4>Contact</h4><p>${cfg.SHOP_ADDRESS}</p><p><a href="tel:${cfg.SHOP_PHONE.replace(/\s/g, '')}">${cfg.SHOP_PHONE}</a></p><p>${cfg.SHOP_EMAIL}</p></div>
</div><div class="copy wrap">&copy; ${new Date().getFullYear()} ${cfg.SHOP_NAME}. All rights reserved.</div></footer>
</body></html>`;
}

function card(ctx, p) {
  const sold = p.stock <= 0;
  const d = discount(p);
  return h`<article class="card">
  <a class="card-img" href="/product/${p.slug}">
    ${sold ? h`<span class="badge out">Sold out</span>` : d ? h`<span class="badge sale">-${d}%</span>` : ''}
    <img src="${imgUrl(p)}" alt="${p.name}" loading="lazy" width="300" height="300">
  </a>
  <div class="card-body">
    <div class="card-brand">${p.brand_name}</div>
    <h3><a href="/product/${p.slug}">${p.name}</a></h3>
    <div class="price">${d ? h`<s>${money(p.price)}</s> ` : ''}<b>${money(effPrice(p))}</b></div>
    <div class="card-actions">
      ${sold ? h`<a class="btn ghost" href="/product/${p.slug}">View</a>` : h`<form method="post" action="/cart/add">${csrf(ctx)}<input type="hidden" name="id" value="${p.id}"><input type="hidden" name="qty" value="1"><button class="btn" type="submit">Add to cart</button></form>`}
      <form method="post" action="/compare/add">${csrf(ctx)}<input type="hidden" name="id" value="${p.id}"><button class="btn ghost" type="submit" title="Add to compare">Compare</button></form>
    </div>
  </div>
</article>`;
}

function home(ctx, { featured, sale, newest, brands }) {
  return h`
<section class="hero">
  <div class="hero-text">
    <p class="eyebrow">Your Ultimate Destination</p>
    <h1>Best Phones. Best Prices.</h1>
    <p>100% genuine company products with warranty. Order online, pay on delivery.</p>
    <a class="btn lg" href="/shop">Shop now</a> <a class="btn lg ghost-light" href="/shop?sale=1">Special offers</a>
  </div>
</section>
<section class="trust">
  <div><b>Islandwide Delivery</b><span>Fast and reliable</span></div>
  <div><b>Cash on Delivery</b><span>Pay when it arrives</span></div>
  <div><b>Genuine Products</b><span>Warranty on every device</span></div>
  <div><b>Friendly Support</b><span>Call or WhatsApp us</span></div>
</section>
<section><h2 class="sec-title">Featured brands</h2>
  <div class="brand-strip">${brands.map((b) => h`<a href="/shop?brand=${b.slug}">${b.name}</a>`)}</div></section>
<section><div class="sec-head"><h2 class="sec-title">Featured phones</h2><a href="/shop?category=phone">View all</a></div>
  <div class="grid">${featured.map((p) => card(ctx, p))}</div></section>
${sale.length ? h`<section><div class="sec-head"><h2 class="sec-title">Special offers</h2><a href="/shop?sale=1">View all</a></div>
  <div class="grid">${sale.map((p) => card(ctx, p))}</div></section>` : ''}
<section><div class="sec-head"><h2 class="sec-title">New arrivals</h2><a href="/shop">View all</a></div>
  <div class="grid">${newest.map((p) => card(ctx, p))}</div></section>`;
}

function shop(ctx, { products, brands, total, page, pages, f, title }) {
  const qs = (over) => {
    const q = { ...f, ...over };
    const parts = Object.entries(q).filter(([, v]) => v !== '' && v != null && v !== false).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`);
    return '/shop' + (parts.length ? '?' + parts.join('&') : '');
  };
  return h`
<div class="crumbs"><a href="/">Home</a> / <span>${title}</span></div>
<div class="shop-layout">
  <aside class="filters">
    <form method="get" action="/shop">
      ${f.q ? h`<input type="hidden" name="q" value="${f.q}">` : ''}
      <label>Category
        <select name="category"><option value="">All</option>
          ${[['phone', 'Mobile Phones'], ['tablet', 'Tablets'], ['accessory', 'Accessories']].map(([v, l]) => h`<option value="${v}" ${f.category === v ? raw('selected') : ''}>${l}</option>`)}
        </select></label>
      <label>Brand
        <select name="brand"><option value="">All brands</option>
          ${brands.map((b) => h`<option value="${b.slug}" ${f.brand === b.slug ? raw('selected') : ''}>${b.name}</option>`)}
        </select></label>
      <label>Min price (Rs.)<input type="number" name="min" min="0" max="10000000" value="${f.min}"></label>
      <label>Max price (Rs.)<input type="number" name="max" min="0" max="10000000" value="${f.max}"></label>
      <label class="check"><input type="checkbox" name="sale" value="1" ${f.sale ? raw('checked') : ''}> On sale only</label>
      <label class="check"><input type="checkbox" name="stock" value="1" ${f.stock ? raw('checked') : ''}> In stock only</label>
      <label>Sort by
        <select name="sort">
          ${[['new', 'Newest'], ['price_asc', 'Price: low to high'], ['price_desc', 'Price: high to low'], ['name', 'Name A-Z']].map(([v, l]) => h`<option value="${v}" ${f.sort === v ? raw('selected') : ''}>${l}</option>`)}
        </select></label>
      <button class="btn" type="submit">Apply filters</button>
      <a class="link-reset" href="/shop">Reset</a>
    </form>
  </aside>
  <section class="results">
    <div class="sec-head"><h1 class="sec-title">${title}</h1><span class="muted">${total} product${total === 1 ? '' : 's'}</span></div>
    ${products.length ? h`<div class="grid">${products.map((p) => card(ctx, p))}</div>` : h`<p class="empty">No products match your search. <a href="/shop">Clear filters</a></p>`}
    ${pages > 1 ? h`<nav class="pager" aria-label="Pages">
      ${page > 1 ? h`<a href="${qs({ page: page - 1 })}">&laquo; Prev</a>` : ''}
      <span>Page ${page} of ${pages}</span>
      ${page < pages ? h`<a href="${qs({ page: page + 1 })}">Next &raquo;</a>` : ''}
    </nav>` : ''}
  </section>
</div>`;
}

function product(ctx, p, related) {
  const sold = p.stock <= 0;
  const d = discount(p);
  const specs = [['Brand', p.brand_name], ['RAM', p.ram], ['Storage', p.storage], ['Display', p.display], ['Camera', p.camera], ['Battery', p.battery], ['Chipset', p.chipset], ['OS', p.os]].filter(([, v]) => v);
  return h`
<div class="crumbs"><a href="/">Home</a> / <a href="/shop?brand=${p.brand_slug}">${p.brand_name}</a> / <span>${p.name}</span></div>
<div class="pdp">
  <div class="pdp-img"><img src="${imgUrl(p)}" alt="${p.name}" width="520" height="520"></div>
  <div class="pdp-info">
    <div class="card-brand">${p.brand_name}</div>
    <h1>${p.name}</h1>
    <div class="price big">${d ? h`<s>${money(p.price)}</s> <span class="badge sale inline">-${d}%</span><br>` : ''}<b>${money(effPrice(p))}</b></div>
    <p class="stock ${sold ? 'out' : p.stock <= 3 ? 'low' : 'in'}">${sold ? 'Sold out' : p.stock <= 3 ? `Only ${p.stock} left` : 'In stock'}</p>
    ${sold ? '' : h`<form method="post" action="/cart/add" class="buy">${csrf(ctx)}<input type="hidden" name="id" value="${p.id}">
      <label>Qty <select name="qty">${[1, 2, 3, 4, 5].filter((n) => n <= p.stock).map((n) => h`<option>${n}</option>`)}</select></label>
      <button class="btn lg" type="submit">Add to cart</button></form>`}
    <form method="post" action="/compare/add" class="inline-form">${csrf(ctx)}<input type="hidden" name="id" value="${p.id}"><button class="btn ghost" type="submit">Add to compare</button></form>
    <ul class="perks"><li>100% genuine, warranty included</li><li>Islandwide delivery</li><li>Cash on delivery available</li></ul>
    <table class="specs"><tbody>${specs.map(([k, v]) => h`<tr><th>${k}</th><td>${v}</td></tr>`)}</tbody></table>
  </div>
</div>
${p.description ? h`<section class="desc"><h2>Description</h2>${paragraphs(p.description)}</section>` : ''}
${related.length ? h`<section><h2 class="sec-title">You may also like</h2><div class="grid">${related.map((r) => card(ctx, r))}</div></section>` : ''}`;
}

function cart(ctx, { lines, subtotal, shipping, total }) {
  if (!lines.length) return h`<h1>Your cart</h1><p class="empty">Your cart is empty. <a href="/shop">Continue shopping</a></p>`;
  return h`<h1>Your cart</h1>
<div class="cart-layout">
  <div class="cart-lines">${lines.map((l) => h`
    <div class="cart-line">
      <img src="${imgUrl(l)}" alt="" width="80" height="80">
      <div class="grow"><a href="/product/${l.slug}">${l.name}</a><div class="muted">${money(l.unit)} each</div></div>
      <form method="post" action="/cart/update" class="qty-form">${csrf(ctx)}<input type="hidden" name="id" value="${l.id}">
        <select name="qty" aria-label="Quantity">${[0, 1, 2, 3, 4, 5].filter((n) => n <= Math.max(l.stock, l.qty) || n === 0).map((n) => h`<option value="${n}" ${n === l.qty ? raw('selected') : ''}>${n === 0 ? 'Remove' : n}</option>`)}</select>
        <button class="btn ghost sm" type="submit">Update</button></form>
      <b class="line-total">${money(l.unit * l.qty)}</b>
    </div>`)}</div>
  <aside class="summary">
    <h3>Order summary</h3>
    <div class="row"><span>Subtotal</span><b>${money(subtotal)}</b></div>
    <div class="row"><span>Delivery</span><b>${shipping ? money(shipping) : 'Free'}</b></div>
    <div class="row total"><span>Total</span><b>${money(total)}</b></div>
    <a class="btn lg block" href="/checkout">Proceed to checkout</a>
    <p class="muted small">Payment: cash on delivery.</p>
  </aside>
</div>`;
}

function checkout(ctx, { lines, subtotal, shipping, total, v = {}, errors = {} }) {
  const err = (k) => (errors[k] ? h`<span class="err">${errors[k]}</span>` : '');
  return h`<h1>Checkout</h1>
<div class="cart-layout">
  <form method="post" action="/checkout" class="form-card" novalidate>
    ${csrf(ctx)}
    <div class="hp" aria-hidden="true"><label>Leave empty<input type="text" name="website" tabindex="-1" autocomplete="off"></label></div>
    <label>Full name ${err('name')}<input name="name" required maxlength="80" autocomplete="name" value="${v.name || ''}"></label>
    <label>Mobile number ${err('phone')}<input name="phone" required maxlength="20" inputmode="tel" autocomplete="tel" placeholder="07X XXX XXXX" value="${v.phone || ''}"></label>
    <label>Delivery address ${err('address')}<textarea name="address" required maxlength="200" rows="3" autocomplete="street-address">${v.address || ''}</textarea></label>
    <label>City / Town ${err('city')}<input name="city" required maxlength="60" autocomplete="address-level2" value="${v.city || ''}"></label>
    <label>Order notes (optional) ${err('notes')}<textarea name="notes" maxlength="300" rows="2">${v.notes || ''}</textarea></label>
    <p class="muted">Payment method: <b>Cash on delivery</b>. We'll confirm your order by phone or WhatsApp.</p>
    <button class="btn lg" type="submit">Place order</button>
  </form>
  <aside class="summary">
    <h3>Your order</h3>
    ${lines.map((l) => h`<div class="row small"><span>${l.name} &times; ${l.qty}</span><b>${money(l.unit * l.qty)}</b></div>`)}
    <div class="row"><span>Delivery</span><b>${shipping ? money(shipping) : 'Free'}</b></div>
    <div class="row total"><span>Total</span><b>${money(total)}</b></div>
  </aside>
</div>`;
}

function orderDone(ctx, o, items) {
  const wa = `https://wa.me/${cfg.WHATSAPP}?text=${encodeURIComponent(`Hello, I placed order ${o.code}. Please confirm.`)}`;
  return h`<div class="form-card center">
  <h1>Thank you, ${o.name.split(' ')[0]}!</h1>
  <p>Your order <b class="code">${o.code}</b> has been received. Status: <b>${o.status}</b>.</p>
  <p class="muted">Keep this order number. You can check its status at any time on this page.</p>
  <table class="specs"><tbody>${items.map((i) => h`<tr><th>${i.name} &times; ${i.qty}</th><td>${money(i.unit_price * i.qty)}</td></tr>`)}
    <tr><th>Delivery</th><td>${o.shipping ? money(o.shipping) : 'Free'}</td></tr>
    <tr><th>Total (pay on delivery)</th><td><b>${money(o.total)}</b></td></tr></tbody></table>
  <p>Delivering to: ${o.city}</p>
  <a class="btn lg" href="${wa}" rel="noopener noreferrer">Confirm on WhatsApp</a>
  <a class="btn ghost" href="/shop">Continue shopping</a>
</div>`;
}

function authForm(ctx, { mode, v = {}, error }) {
  const reg = mode === 'register';
  return h`<div class="form-card narrow">
  <h1>${reg ? 'Create account' : 'Login'}</h1>
  ${error ? h`<div class="flash error">${error}</div>` : ''}
  <form method="post" action="${reg ? '/register' : '/login'}" novalidate>
    ${csrf(ctx)}
    ${reg ? h`<label>Full name<input name="name" required maxlength="80" autocomplete="name" value="${v.name || ''}"></label>` : ''}
    <label>Email<input type="email" name="email" required maxlength="254" autocomplete="email" value="${v.email || ''}"></label>
    ${reg ? h`<label>Mobile (optional)<input name="phone" maxlength="20" autocomplete="tel" value="${v.phone || ''}"></label>` : ''}
    <label>Password<input type="password" name="password" required maxlength="128" autocomplete="${reg ? 'new-password' : 'current-password'}"></label>
    ${reg ? h`<p class="muted small">At least 10 characters, with a mix of letters, numbers or symbols.</p><label>Confirm password<input type="password" name="password2" required maxlength="128" autocomplete="new-password"></label>` : ''}
    <button class="btn lg block" type="submit">${reg ? 'Create account' : 'Login'}</button>
  </form>
  <p class="muted">${reg ? h`Already registered? <a href="/login">Login</a>` : h`No account yet? <a href="/register">Create one</a>`}</p>
</div>`;
}

function account(ctx, { orders, error }) {
  return h`<h1>My account</h1>
<div class="two-col">
  <section class="form-card"><h2>My orders</h2>
    ${orders.length ? h`<table class="specs"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody>
      ${orders.map((o) => h`<tr><td><a href="/order/${o.code}">${o.code}</a></td><td>${new Date(o.created_at * 1000).toISOString().slice(0, 10)}</td><td>${money(o.total)}</td><td>${o.status}</td></tr>`)}</tbody></table>` : h`<p class="muted">No orders yet.</p>`}
  </section>
  <section class="form-card"><h2>Change password</h2>
    ${error ? h`<div class="flash error">${error}</div>` : ''}
    <form method="post" action="/account/password" novalidate>${csrf(ctx)}
      <label>Current password<input type="password" name="current" required maxlength="128" autocomplete="current-password"></label>
      <label>New password<input type="password" name="password" required maxlength="128" autocomplete="new-password"></label>
      <button class="btn" type="submit">Update password</button></form>
    <form method="post" action="/logout" class="mt">${csrf(ctx)}<button class="btn ghost" type="submit">Log out</button></form>
  </section>
</div>`;
}

function compare(ctx, items) {
  if (!items.length) return h`<h1>Compare</h1><p class="empty">Nothing to compare yet. Use the "Compare" button on products. <a href="/shop">Browse products</a></p>`;
  const rows = [['Price', (p) => money(effPrice(p))], ['RAM', (p) => p.ram], ['Storage', (p) => p.storage], ['Display', (p) => p.display], ['Camera', (p) => p.camera], ['Battery', (p) => p.battery], ['Chipset', (p) => p.chipset], ['OS', (p) => p.os]];
  return h`<h1>Compare products</h1>
<div class="table-scroll"><table class="specs compare"><thead><tr><th></th>${items.map((p) => h`<th><a href="/product/${p.slug}"><img src="${imgUrl(p)}" alt="" width="90" height="90"><br>${p.name}</a>
  <form method="post" action="/compare/remove">${csrf(ctx)}<input type="hidden" name="id" value="${p.id}"><button class="btn ghost sm" type="submit">Remove</button></form></th>`)}</tr></thead>
  <tbody>${rows.map(([k, fn]) => h`<tr><th>${k}</th>${items.map((p) => h`<td>${fn(p) || '-'}</td>`)}</tr>`)}</tbody></table></div>`;
}

function contact() {
  return h`<div class="form-card"><h1>Contact us</h1>
  <p>Questions about a product or an order? Reach us any time:</p>
  <ul class="perks"><li>Phone: <a href="tel:${cfg.SHOP_PHONE.replace(/\s/g, '')}">${cfg.SHOP_PHONE}</a></li>
  <li>WhatsApp: <a href="https://wa.me/${cfg.WHATSAPP}" rel="noopener noreferrer">Chat with us</a></li>
  <li>Email: ${cfg.SHOP_EMAIL}</li><li>Address: ${cfg.SHOP_ADDRESS}</li></ul></div>`;
}

const POLICIES = {
  returns: ['Returns & Warranty', 'All devices are sold brand new with the manufacturer or importer warranty. If you receive a faulty or incorrect item, contact us within 7 days of delivery and we will arrange a replacement or refund.\n\nReplace this text with your real return and warranty policy before going live.'],
  privacy: ['Privacy Policy', 'We collect only what is needed to process your order: name, phone number, delivery address and (if you create an account) your email. Passwords are stored as salted hashes and never in readable form. We do not sell your data.\n\nAnalytics are anonymous: we store a daily-rotating hash, never your IP address.\n\nReplace this text with your real privacy policy before going live.'],
  terms: ['Terms & Conditions', 'Prices are in Sri Lankan Rupees and may change without notice. An order is confirmed once our team contacts you. Stock is not reserved until the order is confirmed.\n\nReplace this text with your real terms before going live.'],
};
function policy(key) {
  const p = POLICIES[key];
  if (!p) return null;
  return h`<div class="form-card"><h1>${p[0]}</h1>${paragraphs(p[1])}</div>`;
}

function errorPage(ctx, status, message) {
  return layout(ctx, { title: String(status), body: h`<div class="form-card center"><h1>${status}</h1><p>${message}</p><a class="btn" href="/">Back to home</a></div>`, nav: {} });
}

function productSvg(p, brandName) {
  let hue = 0;
  for (const c of brandName + p.name) hue = (hue * 31 + c.charCodeAt(0)) % 360;
  const tablet = p.category === 'tablet';
  const acc = p.category === 'accessory';
  const w = tablet ? 190 : 120, hgt = tablet ? 250 : 240, x = (300 - w) / 2, y = (300 - hgt) / 2;
  const body = acc
    ? `<rect x="95" y="95" width="110" height="110" rx="22" fill="hsl(${hue} 55% 35%)"/><rect x="135" y="70" width="12" height="30" rx="3" fill="#9aa4b2"/><rect x="153" y="70" width="12" height="30" rx="3" fill="#9aa4b2"/>`
    : `<rect x="${x}" y="${y}" width="${w}" height="${hgt}" rx="${tablet ? 18 : 24}" fill="#161b26"/>
       <rect x="${x + 6}" y="${y + 6}" width="${w - 12}" height="${hgt - 12}" rx="${tablet ? 13 : 19}" fill="url(#g)"/>
       <circle cx="${x + w / 2}" cy="${y + 14}" r="3" fill="#161b26"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 300" width="300" height="300">
<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="hsl(${hue} 70% 55%)"/><stop offset="1" stop-color="hsl(${(hue + 60) % 360} 70% 35%)"/></linearGradient></defs>
<rect width="300" height="300" fill="#f3f5f9"/>${body}
<text x="150" y="288" text-anchor="middle" font-family="sans-serif" font-size="13" fill="#566074">${esc(brandName)}</text></svg>`;
}

