__defs["admin/server.js"] = function (module, exports, require, __dirname) {
'use strict';
// ADMIN PANEL - a completely separate process from the public store.
//  * different port (and by default bound to 127.0.0.1 only), different cookie, different session namespace
//  * no public registration: admins are created from the server console (scripts/create-admin.js)
//  * password + mandatory TOTP two-factor, lockouts, rate limits, idle timeout, audit log
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const config = require('../config');
const { db, now, tx } = require('../lib/db');
const sec = require('../lib/sec');
const { createApp } = require('../lib/http');
const V = require('./views');

const app = createApp({
  name: 'admin',
  cookieName: 'asid',
  sameSite: 'Strict',
  hosts: config.ADMIN_HOSTS,
  assets: require('./assets'),
  idleSec: 20 * 60,          // auto logout after 20 min of inactivity
  absoluteSec: 8 * 3600,     // and never longer than 8 hours
  noStore: true,
  errorPage: (ctx, status, msg) => V.errorPage(ctx, status, msg),
  globalPerMin: 200,
});

const loginLimit = app.limiter({ windowMs: 15 * 60 * 1000, max: 8 });
const mfaLimit = app.limiter({ windowMs: 15 * 60 * 1000, max: 10 });

const MAX_FAILS = 5, LOCK_SECONDS = 15 * 60;
const loadAdmin = (id) => db.prepare('SELECT * FROM admin_users WHERE id = ?').get(id);

// Every response from the admin panel asks search engines to ignore it.
app.get('/robots.txt', (ctx) => ctx.text(200, 'User-agent: *\nDisallow: /\n'));

/* ---------- authentication ---------- */
function guard(handler, { mfa = true } = {}) {
  return async (ctx) => {
    if (!ctx.session || !ctx.session.user_id) return ctx.redirect('/login');
    const a = loadAdmin(ctx.session.user_id);
    if (!a) { ctx.destroySession(); return ctx.redirect('/login'); }
    if (mfa && !ctx.session.mfa) return ctx.redirect(a.totp_enabled ? '/2fa' : '/2fa/setup');
    ctx.admin = a;
    ctx.extraHeaders['X-Robots-Tag'] = 'noindex, nofollow';
    return handler(ctx);
  };
}

app.get('/login', (ctx) => {
  if (ctx.session && ctx.session.user_id && ctx.session.mfa) return ctx.redirect('/');
  if (!ctx.session) ctx.startSession();
  ctx.html(200, V.login(ctx));
});

app.post('/login', async (ctx) => {
  const username = sec.clean(ctx.body.username).slice(0, 40);
  if (!loginLimit(ctx.ip).ok || !loginLimit('u:' + username.toLowerCase()).ok) {
    ctx.audit(username || '-', 'login_rate_limited');
    throw app.httpError(429, 'Too many attempts. Wait 15 minutes.');
  }
  const a = username ? db.prepare('SELECT * FROM admin_users WHERE username = ?').get(username) : null;
  const locked = a && a.locked_until > now();
  const ok = await sec.verifyPassword(String(ctx.body.password || '').slice(0, 128), a ? a.pass_hash : null);
  if (!a || locked || !ok) {
    if (a && !locked) {
      const f = a.failed + 1;
      db.prepare('UPDATE admin_users SET failed = ?, locked_until = ? WHERE id = ?').run(f >= MAX_FAILS ? 0 : f, f >= MAX_FAILS ? now() + LOCK_SECONDS : 0, a.id);
    }
    ctx.audit(username || '-', locked ? 'login_blocked_locked' : 'login_failed');
    ctx.flash('Invalid credentials, or the account is temporarily locked.', 'error');
    return ctx.redirect('/login');
  }
  // password OK -> second factor still required. New session id (anti fixation), mfa = 0.
  ctx.rotateSession({ userId: a.id, mfa: 0 });
  ctx.audit(a.username, 'password_ok');
  ctx.redirect(a.totp_enabled ? '/2fa' : '/2fa/setup');
});

app.get('/2fa', guard((ctx) => {
  if (!ctx.admin.totp_enabled) return ctx.redirect('/2fa/setup');
  if (ctx.session.mfa) return ctx.redirect('/');
  ctx.html(200, V.twofa(ctx));
}, { mfa: false }));

app.post('/2fa', guard(async (ctx) => {
  const a = ctx.admin;
  if (!a.totp_enabled) return ctx.redirect('/2fa/setup');
  if (!mfaLimit(ctx.ip).ok || !mfaLimit('a:' + a.id).ok) throw app.httpError(429, 'Too many attempts. Wait 15 minutes.');
  if (a.locked_until > now()) { ctx.destroySession(); return ctx.redirect('/login'); }
  const step = sec.totpVerify(sec.decrypt(a.totp_secret_enc), ctx.body.code, a.last_totp_step);
  if (!step) {
    const f = a.failed + 1;
    db.prepare('UPDATE admin_users SET failed = ?, locked_until = ? WHERE id = ?').run(f >= MAX_FAILS ? 0 : f, f >= MAX_FAILS ? now() + LOCK_SECONDS : 0, a.id);
    ctx.audit(a.username, '2fa_failed');
    if (f >= MAX_FAILS) { ctx.destroySession(); ctx.flash('Too many failed attempts. Account locked for 15 minutes.', 'error'); return ctx.redirect('/login'); }
    ctx.flash('Invalid code.', 'error');
    return ctx.redirect('/2fa');
  }
  db.prepare('UPDATE admin_users SET last_totp_step = ?, failed = 0, locked_until = 0 WHERE id = ?').run(step, a.id); // a code can never be reused
  ctx.rotateSession({ userId: a.id, mfa: 1 });
  ctx.audit(a.username, 'login_success');
  ctx.redirect('/');
}, { mfa: false }));

app.get('/2fa/setup', guard((ctx) => {
  if (ctx.admin.totp_enabled) return ctx.redirect(ctx.session.mfa ? '/' : '/2fa');
  let secret = ctx.admin.totp_secret_enc ? sec.decrypt(ctx.admin.totp_secret_enc) : null;
  if (!secret) {
    secret = sec.newTotpSecret();
    db.prepare('UPDATE admin_users SET totp_secret_enc = ? WHERE id = ?').run(sec.encrypt(secret), ctx.admin.id);
  }
  const uri = `otpauth://totp/${encodeURIComponent(config.SHOP_NAME + ' Admin')}:${encodeURIComponent(ctx.admin.username)}?secret=${secret}&issuer=${encodeURIComponent(config.SHOP_NAME + ' Admin')}`;
  ctx.html(200, V.twofaSetup(ctx, secret, uri));
}, { mfa: false }));

app.post('/2fa/setup', guard((ctx) => {
  const a = ctx.admin;
  if (a.totp_enabled || !a.totp_secret_enc) return ctx.redirect('/login');
  if (!mfaLimit(ctx.ip).ok) throw app.httpError(429, 'Too many attempts.');
  const step = sec.totpVerify(sec.decrypt(a.totp_secret_enc), ctx.body.code, 0);
  if (!step) { ctx.flash('That code was not correct. Try again.', 'error'); return ctx.redirect('/2fa/setup'); }
  db.prepare('UPDATE admin_users SET totp_enabled = 1, last_totp_step = ? WHERE id = ?').run(step, a.id);
  ctx.rotateSession({ userId: a.id, mfa: 1 });
  ctx.audit(a.username, '2fa_enabled');
  ctx.redirect('/');
}, { mfa: false }));

app.post('/logout', (ctx) => {
  const a = ctx.session && ctx.session.user_id ? loadAdmin(ctx.session.user_id) : null;
  if (a) ctx.audit(a.username, 'logout');
  ctx.destroySession();
  ctx.redirect('/login');
});

/* ---------- dashboard & analytics ---------- */
const LK = 19800; // Sri Lanka = UTC+5:30
const dayExpr = (col) => `strftime('%Y-%m-%d', ${col} + ${LK}, 'unixepoch')`;

function lastDays(n) {
  const out = [];
  for (let i = n - 1; i >= 0; i--) out.push(new Date(Date.now() + LK * 1000 - i * 86400000).toISOString().slice(0, 10));
  return out;
}

app.get('/', guard((ctx) => {
  const t = now(), since = t - 30 * 86400;
  const one = (sql, ...p) => db.prepare(sql).get(...p);
  const all = (sql, ...p) => db.prepare(sql).all(...p);
  const todayStr = lastDays(1)[0];
  const today = one(`SELECT COUNT(*) n, COALESCE(SUM(total),0) rev FROM orders WHERE status != 'cancelled' AND ${dayExpr('created_at')} = ?`, todayStr);
  const m = one("SELECT COUNT(*) n, COALESCE(SUM(total),0) rev FROM orders WHERE status != 'cancelled' AND created_at >= ?", since);
  const days = lastDays(30);
  const revMap = Object.fromEntries(all(`SELECT ${dayExpr('created_at')} d, SUM(total) v FROM orders WHERE status != 'cancelled' AND created_at >= ? GROUP BY d`, since - 86400).map((r) => [r.d, r.v]));
  const visMap = Object.fromEntries(all(`SELECT ${dayExpr('ts')} d, COUNT(DISTINCT visitor) v FROM page_views WHERE ts >= ? GROUP BY d`, since - 86400).map((r) => [r.d, r.v]));
  const v30 = one('SELECT COUNT(*) views FROM page_views WHERE ts >= ?', since).views;
  const visitors = one('SELECT COUNT(*) n FROM (SELECT DISTINCT visitor, ' + dayExpr('ts') + ' d FROM page_views WHERE ts >= ?)', since).n;
  const data = {
    today, m, pending: one("SELECT COUNT(*) n FROM orders WHERE status = 'pending'").n,
    visitors, views: v30,
    customers: one('SELECT COUNT(*) n FROM users').n,
    newCustomers: one('SELECT COUNT(*) n FROM users WHERE created_at >= ?', since).n,
    low: all('SELECT id, name, stock FROM products WHERE active = 1 AND stock <= 3 ORDER BY stock, name LIMIT 10'),
    revByDay: days.map((d) => ({ label: d, value: revMap[d] || 0 })),
    visByDay: days.map((d) => ({ label: d, value: visMap[d] || 0 })),
    byStatus: all('SELECT status label, COUNT(*) value FROM orders GROUP BY status ORDER BY value DESC'),
    byBrand: all(`SELECT b.name label, SUM(oi.unit_price * oi.qty) value FROM order_items oi JOIN orders o ON o.id = oi.order_id
      JOIN products p ON p.id = oi.product_id JOIN brands b ON b.id = p.brand_id WHERE o.status != 'cancelled' AND o.created_at >= ? GROUP BY b.id ORDER BY value DESC LIMIT 8`, since),
    top: all(`SELECT oi.name label, SUM(oi.qty) value FROM order_items oi JOIN orders o ON o.id = oi.order_id
      WHERE o.status != 'cancelled' AND o.created_at >= ? GROUP BY oi.name ORDER BY value DESC LIMIT 6`, since),
    viewed: all(`SELECT p.name label, COUNT(*) value FROM page_views v JOIN products p ON p.id = v.product_id WHERE v.ts >= ? GROUP BY p.id ORDER BY value DESC LIMIT 6`, since),
    recent: all('SELECT id, code, name, total, status FROM orders ORDER BY created_at DESC LIMIT 8'),
  };
  ctx.html(200, V.shell(ctx, { title: 'Dashboard', active: '/', body: V.dashboard(ctx, data) }));
}));

/* ---------- orders ---------- */
app.get('/orders', guard((ctx) => {
  const status = V.STATUSES.includes(ctx.query.status) ? ctx.query.status : '';
  const q = sec.clean(ctx.query.q || '').slice(0, 40);
  const where = [], params = [];
  if (status) { where.push('status = ?'); params.push(status); }
  if (q) { const l = '%' + q.replace(/[\\%_]/g, '\\$&') + '%'; where.push("(code LIKE ? ESCAPE '\\' OR name LIKE ? ESCAPE '\\' OR phone LIKE ? ESCAPE '\\')"); params.push(l, l, l); }
  const rows = db.prepare(`SELECT * FROM orders ${where.length ? 'WHERE ' + where.join(' AND ') : ''} ORDER BY created_at DESC LIMIT 200`).all(...params);
  ctx.html(200, V.shell(ctx, { title: 'Orders', active: '/orders', body: V.orders(ctx, { rows, status, q }) }));
}));

app.get('/orders/:id', guard((ctx) => {
  const o = db.prepare('SELECT * FROM orders WHERE id = ?').get(sec.int(ctx.params.id, 1, 1e9) || 0);
  if (!o) return ctx.html(404, V.errorPage(ctx, 404, 'Order not found'));
  const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(o.id);
  ctx.html(200, V.shell(ctx, { title: 'Order ' + o.code, active: '/orders', body: V.order(ctx, o, items) }));
}));

app.post('/orders/:id/status', guard((ctx) => {
  const id = sec.int(ctx.params.id, 1, 1e9) || 0;
  const to = String(ctx.body.status || '');
  const res = tx(() => {
    const o = db.prepare('SELECT * FROM orders WHERE id = ?').get(id);
    if (!o) return 'Order not found.';
    if (!V.NEXT[o.status].includes(to)) return `Cannot change ${o.status} to ${to}.`;
    if (to === 'cancelled') {
      for (const it of db.prepare('SELECT product_id, qty FROM order_items WHERE order_id = ?').all(o.id)) {
        if (it.product_id) db.prepare('UPDATE products SET stock = stock + ? WHERE id = ?').run(it.qty, it.product_id);
      }
    }
    db.prepare('UPDATE orders SET status = ?, updated_at = ? WHERE id = ?').run(to, now(), o.id);
    ctx.audit(ctx.admin.username, 'order_status', `${o.code}: ${o.status} -> ${to}`);
    return null;
  });
  ctx.flash(res || `Order updated to ${to}.`, res ? 'error' : 'ok');
  ctx.redirect('/orders/' + id);
}));

/* ---------- products ---------- */
const SELECT_P = 'SELECT p.*, b.name AS brand_name FROM products p JOIN brands b ON b.id = p.brand_id';
const brandList = () => db.prepare('SELECT * FROM brands ORDER BY name').all();

app.get('/products', guard((ctx) => {
  const q = sec.clean(ctx.query.q || '').slice(0, 60);
  const rows = q
    ? db.prepare(`${SELECT_P} WHERE p.name LIKE ? ESCAPE '\\' ORDER BY p.name LIMIT 300`).all('%' + q.replace(/[\\%_]/g, '\\$&') + '%')
    : db.prepare(`${SELECT_P} ORDER BY p.name LIMIT 300`).all();
  ctx.html(200, V.shell(ctx, { title: 'Products', active: '/products', body: V.products(ctx, { rows, q }) }));
}));

app.get('/products/new', guard((ctx) => ctx.html(200, V.shell(ctx, { title: 'Add product', active: '/products', body: V.productForm(ctx, { brands: brandList(), isNew: true }) }))));
app.get('/products/:id/edit', guard((ctx) => {
  const p = db.prepare('SELECT * FROM products WHERE id = ?').get(sec.int(ctx.params.id, 1, 1e9) || 0);
  if (!p) return ctx.html(404, V.errorPage(ctx, 404, 'Product not found'));
  ctx.html(200, V.shell(ctx, { title: 'Edit product', active: '/products', body: V.productForm(ctx, { p, brands: brandList() }) }));
}));

const optText = (v, max) => { const s = sec.clean(v); return s.length <= max ? s || null : undefined; };
function parseProduct(b) {
  const errors = {}, v = {};
  v.name = sec.str(b.name, 2, 120); if (!v.name) errors.name = '2-120 characters.';
  v.brand_id = sec.int(b.brand_id, 1, 1e9);
  if (!v.brand_id || !db.prepare('SELECT 1 FROM brands WHERE id = ?').get(v.brand_id)) errors.brand_id = 'Choose a brand.';
  v.category = ['phone', 'tablet', 'accessory'].includes(b.category) ? b.category : (errors.category = 'Invalid');
  v.price = sec.int(b.price, 0, 100000000); if (v.price === null) errors.price = 'Whole number, 0 or more.';
  if (sec.clean(b.sale_price) === '') v.sale_price = null;
  else { v.sale_price = sec.int(b.sale_price, 0, 100000000); if (v.sale_price === null) errors.sale_price = 'Whole number.'; else if (v.price !== null && v.sale_price >= v.price) errors.sale_price = 'Must be lower than the price.'; }
  v.stock = sec.int(b.stock, 0, 100000); if (v.stock === null) errors.stock = 'Whole number, 0 or more.';
  for (const k of ['ram', 'storage', 'display', 'camera', 'battery', 'chipset', 'os']) { v[k] = optText(b[k], 120); if (v[k] === undefined) errors[k] = 'Too long.'; }
  v.description = optText(String(b.description || '').replace(/\r\n/g, '\n'), 4000); if (v.description === undefined) errors.description = 'Too long (4000 max).';
  v.featured = b.featured === '1' ? 1 : 0;
  v.active = b.active === '1' ? 1 : 0;
  return { v, errors };
}

// Validate an uploaded image by its real bytes (never by the filename or declared type) and store under a random name.
function saveImage(file) {
  const d = file.data;
  if (d.length > 2 * 1024 * 1024) return { error: 'Image is larger than 2 MB.' };
  let ext = null;
  if (d.length > 12 && d[0] === 0x89 && d.subarray(1, 4).toString() === 'PNG' && d[4] === 0x0d && d[5] === 0x0a && d[6] === 0x1a && d[7] === 0x0a) ext = 'png';
  else if (d.length > 3 && d[0] === 0xff && d[1] === 0xd8 && d[2] === 0xff) ext = 'jpg';
  else if (d.length > 12 && d.subarray(0, 4).toString() === 'RIFF' && d.subarray(8, 12).toString() === 'WEBP') ext = 'webp';
  if (!ext) return { error: 'Only real PNG, JPG or WebP images are accepted.' };
  const name = crypto.randomBytes(16).toString('hex') + '.' + ext;
  fs.writeFileSync(path.join(config.UPLOAD_DIR, name), d, { mode: 0o600 });
  return { name };
}
const removeImage = (name) => { if (name && /^[a-f0-9]{32}\.(png|jpg|webp)$/.test(name)) fs.rm(path.join(config.UPLOAD_DIR, name), () => {}); };

function uniqueSlug(name, exceptId = 0) {
  const base = sec.slugify(name);
  let s = base, i = 2;
  while (db.prepare('SELECT 1 FROM products WHERE slug = ? AND id != ?').get(s, exceptId)) s = `${base}-${i++}`;
  return s;
}

async function saveProduct(ctx, existing) {
  const { v, errors } = parseProduct(ctx.body);
  let img = null;
  if (ctx.files.image) { img = saveImage(ctx.files.image); if (img.error) errors.image = img.error; }
  if (Object.keys(errors).length) {
    if (img && img.name) removeImage(img.name);
    return ctx.html(422, V.shell(ctx, { title: existing ? 'Edit product' : 'Add product', active: '/products', body: V.productForm(ctx, { p: { ...ctx.body, id: existing && existing.id, image: existing && existing.image }, brands: brandList(), errors, isNew: !existing }) }));
  }
  const t = now();
  if (!existing) {
    const r = db.prepare(`INSERT INTO products(brand_id,category,name,slug,price,sale_price,stock,ram,storage,display,camera,battery,chipset,os,description,image,featured,active,created_at,updated_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(v.brand_id, v.category, v.name, uniqueSlug(v.name), v.price, v.sale_price, v.stock, v.ram, v.storage, v.display, v.camera, v.battery, v.chipset, v.os, v.description, img ? img.name : null, v.featured, v.active, t, t);
    ctx.audit(ctx.admin.username, 'product_create', `#${r.lastInsertRowid} ${v.name}`);
  } else {
    db.prepare(`UPDATE products SET brand_id=?,category=?,name=?,slug=?,price=?,sale_price=?,stock=?,ram=?,storage=?,display=?,camera=?,battery=?,chipset=?,os=?,description=?,image=?,featured=?,active=?,updated_at=? WHERE id=?`)
      .run(v.brand_id, v.category, v.name, uniqueSlug(v.name, existing.id), v.price, v.sale_price, v.stock, v.ram, v.storage, v.display, v.camera, v.battery, v.chipset, v.os, v.description, img ? img.name : existing.image, v.featured, v.active, t, existing.id);
    if (img) removeImage(existing.image);
    ctx.audit(ctx.admin.username, 'product_update', `#${existing.id} ${v.name}`);
  }
  ctx.flash('Product saved.', 'ok');
  ctx.redirect('/products');
}

app.post('/products/new', guard((ctx) => saveProduct(ctx, null)), { multipart: true, maxBody: 3 * 1024 * 1024 });
app.post('/products/:id/edit', guard((ctx) => {
  const p = db.prepare('SELECT * FROM products WHERE id = ?').get(sec.int(ctx.params.id, 1, 1e9) || 0);
  if (!p) return ctx.html(404, V.errorPage(ctx, 404, 'Product not found'));
  return saveProduct(ctx, p);
}), { multipart: true, maxBody: 3 * 1024 * 1024 });

app.post('/products/:id/toggle', guard((ctx) => {
  const id = sec.int(ctx.params.id, 1, 1e9) || 0;
  const r = db.prepare('UPDATE products SET active = 1 - active, updated_at = ? WHERE id = ?').run(now(), id);
  if (r.changes) ctx.audit(ctx.admin.username, 'product_toggle', `#${id}`);
  ctx.redirect('/products');
}));

/* ---------- brands ---------- */
const brandsPage = (ctx, error) => ctx.html(error ? 422 : 200, V.shell(ctx, { title: 'Brands', active: '/brands', body: V.brands(ctx, db.prepare('SELECT b.*, (SELECT COUNT(*) FROM products p WHERE p.brand_id = b.id) n FROM brands b ORDER BY b.name').all(), error) }));
app.get('/brands', guard((ctx) => brandsPage(ctx)));
app.post('/brands/add', guard((ctx) => {
  const name = sec.str(ctx.body.name, 2, 40);
  if (!name) return brandsPage(ctx, 'Brand name must be 2-40 characters.');
  try { db.prepare('INSERT INTO brands(name, slug) VALUES (?,?)').run(name, sec.slugify(name)); ctx.audit(ctx.admin.username, 'brand_add', name); }
  catch (e) { if (/UNIQUE/i.test(e.message)) return brandsPage(ctx, 'That brand already exists.'); throw e; }
  ctx.redirect('/brands');
}));
app.post('/brands/:id/rename', guard((ctx) => {
  const name = sec.str(ctx.body.name, 2, 40), id = sec.int(ctx.params.id, 1, 1e9);
  if (!name || !id) return brandsPage(ctx, 'Brand name must be 2-40 characters.');
  try { db.prepare('UPDATE brands SET name = ?, slug = ? WHERE id = ?').run(name, sec.slugify(name), id); ctx.audit(ctx.admin.username, 'brand_rename', `#${id} -> ${name}`); }
  catch (e) { if (/UNIQUE/i.test(e.message)) return brandsPage(ctx, 'That brand name is already used.'); throw e; }
  ctx.redirect('/brands');
}));

/* ---------- customers, audit ---------- */
app.get('/customers', guard((ctx) => {
  const rows = db.prepare(`SELECT u.*, (SELECT COUNT(*) FROM orders o WHERE o.user_id = u.id AND o.status != 'cancelled') orders,
    (SELECT COALESCE(SUM(total),0) FROM orders o WHERE o.user_id = u.id AND o.status != 'cancelled') spent FROM users u ORDER BY u.created_at DESC LIMIT 500`).all();
  ctx.html(200, V.shell(ctx, { title: 'Customers', active: '/customers', body: V.customers(ctx, rows) }));
}));
app.get('/audit', guard((ctx) => ctx.html(200, V.shell(ctx, { title: 'Audit log', active: '/audit', body: V.audit(ctx, db.prepare('SELECT * FROM audit_log ORDER BY id DESC LIMIT 200').all()) }))));

/* ---------- my account ---------- */
app.get('/account', guard((ctx) => ctx.html(200, V.shell(ctx, { title: 'My account', active: '/account', body: V.account(ctx) }))));
app.post('/account/password', guard(async (ctx) => {
  const a = ctx.admin;
  const fail = (m) => ctx.html(422, V.shell(ctx, { title: 'My account', active: '/account', body: V.account(ctx, m) }));
  if (!mfaLimit(ctx.ip).ok) throw app.httpError(429, 'Too many attempts.');
  if (!(await sec.verifyPassword(String(ctx.body.current || '').slice(0, 128), a.pass_hash))) return fail('Current password is incorrect.');
  const step = sec.totpVerify(sec.decrypt(a.totp_secret_enc), ctx.body.code, a.last_totp_step);
  if (!step) return fail('Invalid 2FA code.');
  const problem = sec.passwordProblem(ctx.body.password, { min: 12, context: [a.username] });
  if (problem) return fail(problem);
  db.prepare('UPDATE admin_users SET pass_hash = ?, last_totp_step = ? WHERE id = ?').run(await sec.hashPassword(ctx.body.password), step, a.id);
  db.prepare("DELETE FROM sessions WHERE kind = 'admin' AND user_id = ? AND id_hash != ?").run(a.id, ctx.session.id_hash);
  ctx.audit(a.username, 'password_changed');
  ctx.flash('Password changed. Other sessions were signed out.', 'ok');
  ctx.redirect('/account');
}));
app.post('/account/logout-all', guard((ctx) => {
  db.prepare("DELETE FROM sessions WHERE kind = 'admin' AND user_id = ?").run(ctx.admin.id);
  ctx.audit(ctx.admin.username, 'logout_all');
  ctx.destroySession();
  ctx.redirect('/login');
}));

module.exports = app;

};

